{
  "mechanisms": [
    {
      "name": "separate_learning_rates",
      "title": "Separate Learning Rates",
      "description": "The model uses distinct learning rates for updating Stage 1 and Stage 2 values.",
      "params": [
        {
          "name": "alpha_1",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_2",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha_1 * delta_stage1\n\n        delta_stage2 = reward[trial] - q_stage2_mf[state_idx, action_2[trial]]\n        q_stage2_mf[state_idx, action_2[trial]] += alpha_2 * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Stage 1 values are computed as a weighted average of model-based and model-free values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A perseveration parameter adds a bonus to the Stage 1 action chosen on the previous trial.",
      "params": [
        {
          "name": "p",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "pers = np.zeros(2)\n        if last_choice != -1:\n            pers[last_choice] = 1\n            \n        q_stage1_combined = q_stage1_net + p * pers",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage 1 model-free values are updated by the Stage 2 reward prediction error scaled by an eligibility trace.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha_1 * lam * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
